const QUICK_PREFIX='bible-study-quick-v1:';
function readQuick(key){try{let a=JSON.parse(localStorage.getItem(QUICK_PREFIX+key)||'[]');return Array.isArray(a)?a.filter(x=>typeof x==='string').slice(0,50):[]}catch{return []}}
function writeQuick(key,list){try{localStorage.setItem(QUICK_PREFIX+key,JSON.stringify(list))}catch{}}
function rememberPerson(name){let r=readQuick('recent').filter(x=>x!==name);r.unshift(name);writeQuick('recent',r.slice(0,5))}
function toggleFavorite(name){let fav=readQuick('favorites'),exists=fav.includes(name);writeQuick('favorites',exists?fav.filter(x=>x!==name):[name,...fav]);return !exists}
function renderQuick(){const box=$('#quick-links');if(!box)return;const valid=new Set(allPeople().map(p=>p.name)),fav=readQuick('favorites').filter(x=>valid.has(x)),recent=readQuick('recent').filter(x=>valid.has(x)&&!fav.includes(x));const chips=items=>items.map(x=>`<a href="${idHash(x)}">${esc(displayName(x))}</a>`).join('');box.innerHTML=(fav.length?`<div class="quick-row"><span>즐겨찾기</span><div class="quick-items">${chips(fav)}</div></div>`:'')+(recent.length?`<div class="quick-row"><span>최근 본 인물</span><div class="quick-items">${chips(recent)}</div><button type="button" class="tool-icon" id="clear-recent" aria-label="최근 본 인물 지우기" title="최근 본 인물 지우기">${UI_TRASH}</button></div>`:'');$('#clear-recent')?.addEventListener('click',()=>{writeQuick('recent',[]);renderQuick()})}
