const UI_SORT_ORDER=uiIcon('<path d="M7 21V3"/><path d="m4 6 3-3 3 3"/><path d="M17 3v18"/><path d="m14 18 3 3 3-3"/>');
let personOrder={ready:false,revision:0,items:[]},orderDraft=null,orderSelected='',orderSaving=false,orderReturnScroll=0,orderReturnQuery='';
async function loadPersonOrder(){try{const r=await fetch(BASE+'/rest/v1/study_person_order?select=revision,items&id=eq.true',{headers});if(!r.ok)throw Error();const data=await r.json(),row=data[0];if(!row||!Number.isSafeInteger(Number(row.revision))||!Array.isArray(row.items))throw Error();personOrder={ready:true,revision:Number(row.revision),items:row.items}}catch{personOrder={ready:false,revision:0,items:[]}}}
function orderedPeople(){const base=groups.flatMap(([era,names])=>names.map(name=>({name,era,search_term:''}))).concat(people),known=new Map(base.map(p=>[p.name,p])),used=new Set(),buckets=new Map(eraNames.map(era=>[era,[]]));for(const item of personOrder.items){const p=known.get(item?.name);if(p&&!used.has(p.name)&&buckets.has(item.era)){used.add(p.name);buckets.get(item.era).push({...p,era:item.era})}}for(const p of base)if(!used.has(p.name)&&buckets.has(p.era)){used.add(p.name);buckets.get(p.era).push(p)}return eraNames.flatMap(era=>buckets.get(era))}
function openPersonOrder(focusName=''){if(!personOrder.ready){alert('순서 변경을 사용하려면 저장 공간 설정이 필요합니다.');return}orderReturnScroll=window.scrollY;orderReturnQuery=query;orderDraft=allPeople().map(p=>({name:p.name,era:p.era}));orderSelected=focusName;query='';renderPersonOrder();if(focusName)requestAnimationFrame(()=>document.querySelector('[data-order-name="'+CSS.escape(focusName)+'"]')?.scrollIntoView({block:'center'}));else window.scrollTo(0,0)}
function finishPersonOrder(){orderDraft=null;query=orderReturnQuery;peopleView();requestAnimationFrame(()=>{window.scrollTo(0,orderReturnScroll);routeScrolls.set(location.hash||'#/home',window.scrollY)})}
function moveOrder(name,targetName,after){const from=orderDraft.findIndex(x=>x.name===name),to=orderDraft.findIndex(x=>x.name===targetName);if(from<0||to<0||from===to)return;const target=orderDraft[to],item=orderDraft.splice(from,1)[0];item.era=target.era;const destination=orderDraft.findIndex(x=>x.name===targetName)+(after?1:0);orderDraft.splice(destination,0,item);orderSelected=name}
function renderPersonOrder(){if(!orderDraft)return;const bandColors=['#e8efea','#f2ece2','#eaf0e6','#f2ebe6','#e9eeed','#f1eee2','#edece9','#e8efed'];$('#app').innerHTML=`<div class="workspace order-workspace"><div class="order-head"><h1>인물 순서</h1></div><div class="order-list" id="order-list">${orderDraft.map((p,i)=>{const ix=eraNames.indexOf(p.era);return `<div class="order-row ${orderSelected===p.name?'order-selected':''}" data-order-name="${esc(p.name)}" style="--order-band:${bandColors[ix]||bandColors[0]}"><span class="order-name">${personLabel(p.name)}</span><div class="order-arrows"><button type="button" class="tool-icon" data-order-up="${esc(p.name)}" aria-label="${esc(displayName(p.name))} 위로 이동" ${i===0?'disabled':''}>${UI_CHEVRON_LEFT}</button><button type="button" class="tool-icon" data-order-down="${esc(p.name)}" aria-label="${esc(displayName(p.name))} 아래로 이동" ${i===orderDraft.length-1?'disabled':''}>${UI_CHEVRON_RIGHT}</button></div><button type="button" class="order-handle" data-order-handle="${esc(p.name)}" aria-label="${esc(displayName(p.name))} 순서 끌어서 이동" title="끌어서 이동"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="9" cy="5" r="1.5"/><circle cx="15" cy="5" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="19" r="1.5"/><circle cx="15" cy="19" r="1.5"/></svg></button></div>`}).join('')}</div><div class="order-toolbar"><p id="order-status" role="status" class="small"></p><button type="button" class="secondary" id="order-cancel">취소</button><button type="button" class="primary" id="order-save">순서 저장</button></div></div>`;$('#order-cancel').onclick=()=>{if(orderSaving)return;finishPersonOrder()};$('#order-save').onclick=savePersonOrder;document.querySelectorAll('[data-order-up],[data-order-down]').forEach(b=>b.onclick=()=>{const name=b.dataset.orderUp||b.dataset.orderDown,index=orderDraft.findIndex(x=>x.name===name),up=!!b.dataset.orderUp,other=orderDraft[index+(up?-1:1)];if(!other)return;const top=window.scrollY;moveOrder(name,other.name,!up);renderPersonOrder();window.scrollTo(0,top);document.querySelector(`[data-order-${up?'up':'down'}="${CSS.escape(name)}"]`)?.focus({preventScroll:true})});bindOrderDrag()}
async function savePersonOrder(){if(orderSaving||!orderDraft)return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;orderSaving=true;$('#order-save').disabled=true;try{const result=await rpc('study_person_order_save',{p_password:password,p_items:orderDraft,p_revision:personOrder.revision});if(!result?.ok)throw Error(result?.error||'순서를 저장하지 못했습니다.');personOrder={ready:true,revision:Number(result.revision),items:orderDraft.map(x=>({...x}))};finishPersonOrder()}catch(err){$('#order-status').textContent=err.message}finally{orderSaving=false;const save=$('#order-save');if(save)save.disabled=false}}
function bindOrderDrag(){let drag=null,frame=0;const clearMarker=()=>document.querySelectorAll('.drop-before,.drop-after').forEach(e=>e.classList.remove('drop-before','drop-after'));const update=()=>{if(!drag)return;const el=document.elementFromPoint(drag.x,drag.y)?.closest('.order-row');clearMarker();drag.target=null;if(el&&el.dataset.orderName!==drag.name){const r=el.getBoundingClientRect();drag.target=el.dataset.orderName;drag.after=drag.y>r.top+r.height/2;el.classList.add(drag.after?'drop-after':'drop-before')}};const auto=()=>{if(!drag)return;const edge=85,speed=drag.y<edge?-Math.ceil((edge-drag.y)/8):drag.y>innerHeight-edge?Math.ceil((drag.y-(innerHeight-edge))/8):0;if(speed){window.scrollBy(0,speed);update()}frame=requestAnimationFrame(auto)};document.querySelectorAll('[data-order-handle]').forEach(handle=>handle.addEventListener('pointerdown',e=>{if(e.button!==0||drag)return;e.preventDefault();handle.setPointerCapture(e.pointerId);drag={name:handle.dataset.orderHandle,x:e.clientX,y:e.clientY,target:null,after:false,pointer:e.pointerId};handle.closest('.order-row').classList.add('order-dragging');frame=requestAnimationFrame(auto)}));document.querySelectorAll('[data-order-handle]').forEach(handle=>{handle.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.pointer)return;drag.x=e.clientX;drag.y=e.clientY;update()});const finish=(e,cancel)=>{if(!drag||e.pointerId!==drag.pointer)return;const {name,target,after}=drag;drag=null;cancelAnimationFrame(frame);clearMarker();if(!cancel&&target){const top=window.scrollY;moveOrder(name,target,after);renderPersonOrder();window.scrollTo(0,top)}else handle.closest('.order-row')?.classList.remove('order-dragging')};handle.addEventListener('pointerup',e=>finish(e,false));handle.addEventListener('pointercancel',e=>finish(e,true))})}

function sideNotes(list,author){if(!list.length)return '';return list.slice(0,3).map(n=>`<a href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}" class="side-note side-${author}" aria-label="${author==='mine'?'민수':'보라'}: ${esc(n.title)}">${esc(n.title)}</a>`).join('')+(list.length>3?`<a class="side-note side-more side-${author}" href="${idHash(list[0].person)}">${list.length-3}개 더 보기</a>`:'')}
function personLabel(name){const label=displayName(name),m=label.match(/^(.*?) \((.+)\)$/),main=m?m[1]:label,detail=m?m[2]:(name==='스가랴'?'예언자':'');return `<span>${esc(main)}</span>${detail?`<small>${esc(detail)}</small>`:''}`}
function renderPeopleResults(){
 const q=query.trim().toLocaleLowerCase(),all=allPeople(),matching=all.filter(p=>!q||(p.name+' '+displayName(p.name)+' '+p.era+' '+notes.filter(n=>n.person===p.name).map(n=>[n.title,n.body,n.verse,n.topic,n.book].join(' ')).join(' ')).toLocaleLowerCase().includes(q));
 const hits=q?notes.filter(n=>[n.person,displayName(n.person),n.title,n.body,n.verse,n.topic,n.book,n.author==='mine'?'민수':'보라'].join(' ').toLocaleLowerCase().includes(q)):[];
 const hitHtml=hits.length?`<section class="search-hits"><h3>관련 연구 기록 <span class="count">${hits.length}</span></h3>${hits.map(n=>`<a class="explore-note" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><b>${esc(n.title)}</b><small>${esc(displayName(n.person))} · ${personIdentity(n.author)}${n.verse?' · '+esc(n.verse):''}</small><small>${esc(n.body.slice(0,90))}${n.body.length>90?'…':''}</small></span><span>→</span></a>`).join('')}</section>`:'';
 const sections=eraNames.map((era,index)=>{const list=matching.filter(p=>p.era===era);if(!list.length)return '';return `<section class="era-band era-band-${index}" aria-label="${esc(era)}">${list.map(p=>{const ns=notes.filter(n=>n.person===p.name);return `<div class="person-row ${ns.length?'has-notes':'no-notes'}"><div class="side">${sideNotes(ns.filter(n=>n.author==='mine'),'mine')}</div><a class="person" href="${idHash(p.name)}" aria-label="${esc(displayName(p.name))}${p.name==='스가랴'?' 예언자':''}">${personLabel(p.name)}</a><div class="side">${sideNotes(ns.filter(n=>n.author==='bora'),'bora')}</div></div>`}).join('')}</section>`}).join('');
 $('#results').innerHTML=(sections||(!hitHtml?'<div class="empty">검색 결과가 없습니다.</div>':''))+hitHtml;
}

