 $('#app').innerHTML=`<section class="study-home" aria-label="연구 분야"><div id="home-verses" class="home-verses"></div><nav class="home-categories" aria-label="연구 분야">${categories.map(([path,label,icon])=>`<a href="#/${path}" class="home-category"><span class="category-label"><svg class="category-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon}</svg><span><span>${label}</span>${path==='family'&&latestFamily?`<small class="category-detail">${esc(latestFamily.title)} · ${esc(date(latestFamily.created_at))}</small>`:''}</span></span><span class="category-arrow" aria-hidden="true">→</span></a>`).join('')}</nav>${recentNotes.length?`<section class="home-recent"><h2>최근 연구</h2>${recentNotes.map(n=>`<a class="home-entry" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span class="home-entry-text"><small>${esc(displayName(n.person))} · ${personIdentity(n.author)} · ${esc(date(n.created_at))}</small><strong>${esc(n.title)}</strong><span class="home-excerpt">${esc(n.body)}</span></span><span class="home-entry-photo" data-home-photo="${esc(n.id)}" hidden></span></a>`).join('')}</section>`:''}<div class="home-quick" id="quick-links"></div><div class="home-tools"><button type="button" class="home-settings tool-icon" id="manage-open" aria-label="설정" title="설정">${UI_SETTINGS}</button></div></section>`;
