function exploreView(kind){const config={books:['','성경 책','성경 책을 직접 연구하거나 관련 인물 기록을 모아 봅니다.','book','book','성경 책','예: 창세기'],topics:['','주제','한 가지 주제를 직접 연구하거나 관련 기록을 모아 봅니다.','topic','topic','주제','예: 믿음'],verses:['','성구','성구를 직접 묵상하거나 관련 기록을 모아 봅니다.','verse','verse','성구','예: 시편 23:1']}[kind];let groupsMap=new Map();for(const n of notes){const values=kind==='topics'?(n.topic||'').split(','):[n[config[3]]||''];for(let v of values){v=v.trim();if(v){if(!groupsMap.has(v))groupsMap.set(v,[]);groupsMap.get(v).push(n)}}}const list=[...groupsMap].sort((a,b)=>a[0].localeCompare(b[0],'ko'));$('#app').innerHTML=`<div class="workspace explore-workspace"><div class="section-row"><h1 class="people-title">${config[1]}</h1><div class="explore-actions">${kind==='topics'?`<button class="search-toggle" type="button" id="topic-search-toggle" aria-label="주제 검색 열기" aria-expanded="false"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path></svg></button>`:''}<button type="button" class="action-icon" id="new-context" aria-label="${esc(config[1])} 연구 추가" title="${esc(config[1])} 연구 추가">${UI_PLUS}</button></div></div>${kind==='topics'?`<div class="topic-search"><label id="topic-search-panel" hidden><span class="sr-only">주제 검색</span><input type="search" id="topic-search" placeholder="주제 검색"></label></div>`+suggestedTopics():''}${list.length?list.map(([k,ns])=>`<section class="explore-group"><h2><a href="${idHash('@'+config[4]+':'+k)}">${esc(k)}</a> <span class="count">${ns.length}</span></h2>${ns.map(n=>`<a class="explore-note" href="${idHash(n.person)}?note=${encodeURIComponent(n.id)}"><span><b>${esc(n.title)}</b><small>${esc(displayName(n.person))} · ${personIdentity(n.author)}</small></span><span>→</span></a>`).join('')}</section>`).join(''):'<div class="empty">기록 없음</div>'}</div><a class="back bottom-back" href="#/home">← 처음</a>`;const open=()=>{newContextKind=config[4];$('#context-title').textContent=config[5]+' 연구 시작';$('#context-label').textContent=config[5];$('#context-name').placeholder=config[6];$('#context-name').value='';$('#context-dialog').showModal()};$('#new-context').onclick=open;document.querySelector('#empty-context')?.addEventListener('click',open);$('#topic-search-toggle')?.addEventListener('click',e=>{const panel=$('#topic-search-panel'),open=panel.hidden;panel.hidden=!open;e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'주제 검색 닫기':'주제 검색 열기');if(open)$('#topic-search').focus();else{$('#topic-search').value='';$('#topic-search').dispatchEvent(new Event('input'))}});$('#topic-search')?.addEventListener('input',e=>{const q=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.topic-suggestions section').forEach(section=>{let count=0;section.querySelectorAll('a').forEach(a=>{a.hidden=!!q&&!a.textContent.toLocaleLowerCase().includes(q);if(!a.hidden)count++});section.hidden=!count});document.querySelectorAll('.explore-group').forEach(group=>{group.hidden=!!q&&!group.textContent.toLocaleLowerCase().includes(q)})})}
$('#context-form').onsubmit=e=>{e.preventDefault();const name=$('#context-name').value.trim();if(!name)return;$('#context-dialog').close();location.hash=idHash('@'+newContextKind+':'+name)};
const routeScrolls=new Map();
function route(){const hash=location.hash||'#/home';const [path,qs]=hash.startsWith('#/')?hash.slice(2).split('?'):['home',''];const parts=path.split('/');const kind=parts[0]||'home';if(kind==='person'){let name;try{name=resolvePersonName(decodeURIComponent(parts.slice(1).join('/')))}catch{name=''}personNotesFilter='all';personView(name);const noteId=new URLSearchParams(qs||'').get('note');if(noteId)setTimeout(()=>{const el=document.getElementById('note-'+noteId);if(el){el.classList.add('note-highlight');el.scrollIntoView({block:'center',behavior:'smooth'});setTimeout(()=>el.classList.remove('note-highlight'),4000)}},100)}else if(kind==='people')peopleView();else if(kind==='family')familyView();else if(kind==='routine')routineView();else if(['books','topics','verses'].includes(kind))exploreView(kind);else homeView();requestAnimationFrame(()=>window.scrollTo(0,routeScrolls.get(hash)||0))}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a)routeScrolls.set(location.hash||'#/home',window.scrollY)});
window.addEventListener('scroll',()=>{routeScrolls.set(location.hash||'#/home',window.scrollY)},{passive:true});

function displayImage(src,noteId,description=''){const parent=document.querySelector('[data-images="'+noteId+'"]');if(!parent)return;const image=document.createElement('img');image.className='note-image';image.alt=description||'첨부 이미지';image.setAttribute('role','button');image.setAttribute('aria-label',(description||'첨부 이미지')+' 크게 보기');image.tabIndex=0;image.src=src;image.onclick=()=>{$('#full-image').src=src;$('#image-dialog').showModal()};image.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();image.click()}};parent.append(image)}
function fileUrl(path){return BASE+'/storage/v1/object/public/bible-study-photos/'+path.split('/').map(encodeURIComponent).join('/')}
async function loadImages(ns){if(!ns.length)return;const ids=ns.map(n=>n.id).filter(id=>/^[0-9a-f-]{36}$/i.test(id));if(!ids.length)return;try{const url='note_id=in.('+ids.join(',')+')';const [a,b]=await Promise.all([fetch(BASE+'/rest/v1/study_images?select=note_id,data_url'+(descriptionsAvailable?',alt_text':'')+'&'+url,{headers}),fetch(BASE+'/rest/v1/study_files?select=note_id,path'+(descriptionsAvailable?',alt_text':'')+'&'+url,{headers})]);if(!a.ok||!b.ok)throw Error();const legacy=await a.json(),files=await b.json();for(const img of legacy)if(/^data:image\/(jpeg|png|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(img.data_url))displayImage(img.data_url,img.note_id,img.alt_text);files.sort((x,y)=>x.path.split('/').pop().localeCompare(y.path.split('/').pop()));for(const f of files)if(/^[0-9a-f]{64}\/[0-9a-f-]{36}\.(jpg|png|webp|gif)$/.test(f.path))displayImage(fileUrl(f.path),f.note_id,f.alt_text)}catch{document.querySelectorAll('[data-images]').forEach(x=>x.textContent='이미지를 불러오지 못했습니다.')}}
async function rpc(name,payload){const r=await fetch(BASE+'/rest/v1/rpc/'+name,{method:'POST',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify(payload)});const value=await r.json().catch(()=>null);if(!r.ok){const error=Error(value?.message||'요청을 완료하지 못했습니다.');error.code=value?.code;throw error}return value}
async function issueUpload(password){const result=await rpc('study_issue_upload',{p_password:password});if(!result?.ok)throw Error(result?.error||'이미지 업로드를 시작하지 못했습니다.');return result.token}
async function uploadData(data,token,position=0){const blob=await (await fetch(data)).blob(),ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'}[blob.type];if(!ext||blob.size>5242880)throw Error('지원하지 않는 이미지 형식이거나 5MB를 초과했습니다.');const path=token+'/'+position.toString(16)+crypto.randomUUID().slice(1)+'.'+ext;const r=await fetch(BASE+'/storage/v1/object/bible-study-photos/'+path,{method:'POST',headers:{...headers,'Content-Type':blob.type},body:blob});if(!r.ok)throw Error('이미지를 올리지 못했습니다. 잠시 후 다시 시도해 주세요.');return path}
async function cleanup(){try{const paths=await rpc('study_cleanup_candidates',{});if(!paths?.length)return;const r=await fetch(BASE+'/storage/v1/object/bible-study-photos',{method:'DELETE',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({prefixes:paths})});if(r.ok)await rpc('study_cleanup_done',{p_paths:paths})}catch{}}
async function abandon(token){if(token){try{await rpc('study_abandon_upload',{p_token:token});await cleanup()}catch{}}}

function bindNotes(){document.querySelectorAll('[data-copy-note]').forEach(b=>b.onclick=async()=>{const n=notes.find(x=>x.id===b.dataset.copyNote);if(!n)return;const url=location.origin+location.pathname+idHash(n.person)+'?note='+encodeURIComponent(n.id);try{await navigator.clipboard.writeText(url);b.innerHTML=UI_CHECK;b.setAttribute('aria-label','링크를 복사했어요');b.title='링크를 복사했어요';b.parentElement.querySelector('[data-copy-status]').textContent='링크를 복사했어요';setTimeout(()=>{b.innerHTML=UI_LINK;b.setAttribute('aria-label','기록 링크 복사');b.title='기록 링크 복사';const status=b.parentElement?.querySelector('[data-copy-status]');if(status)status.textContent=''},2500)}catch{prompt('아래 주소를 복사해 주세요.',url)}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('이 기록과 첨부 이미지를 삭제할까요?'))return;let p=prompt('작성 비밀번호를 입력해 주세요.');if(p===null)return;try{await change('delete',{id:b.dataset.delete},p);cleanup();await load();personView(currentPerson)}catch(e){alert(e.message)}})}
const DRAFT_PREFIX='bible-study-draft-v2:';
const draftFields=['author','note-title','note-body','note-book','note-verse','note-topic','note-url'];
function draftKey(){return DRAFT_PREFIX+encodeURIComponent(currentPerson)+':'+(editingId||'new')}
function draftSnapshot(){return JSON.stringify(Object.fromEntries(draftFields.map(id=>[id,$('#'+id).value])))}
function saveDraft(){if(!$('#edit-dialog').open)return;try{const snapshot=draftSnapshot();if(snapshot!==draftBaseline)localStorage.setItem(draftKey(),snapshot);else localStorage.removeItem(draftKey())}catch{}}
function closeEditor(){if(!$('#edit-dialog').open)return;const dirty=draftSnapshot()!==draftBaseline||imagesChanged;if(dirty&&!confirm('작성 중인 글은 이 기기에 임시 저장됩니다. 이미지와 비밀번호는 다시 선택해야 합니다. 닫을까요?'))return;saveDraft();$('#edit-dialog').close()}
function renderEditorImages(){const box=$('#image-previews');box.innerHTML=editorImages.map((img,i)=>`<div class="preview-card"><img src="${esc(img.src)}" alt="첨부 이미지 ${i+1}">${descriptionsAvailable?`<label class="image-description">사진 설명<input type="text" maxlength="150" data-img-alt="${i}" value="${esc(img.description||'')}" placeholder="선택 사항"></label>`:''}<div><button type="button" class="tool-icon" data-img-up="${i}" ${i===0?'disabled':''} aria-label="이미지 ${i+1} 앞으로 이동" title="앞으로 이동">${UI_ARROW_LEFT}</button><button type="button" class="tool-icon" data-img-down="${i}" ${i===editorImages.length-1?'disabled':''} aria-label="이미지 ${i+1} 뒤로 이동" title="뒤로 이동">${UI_ARROW_RIGHT}</button><button type="button" class="tool-icon" data-img-remove="${i}" aria-label="이미지 ${i+1} 삭제" title="이미지 삭제">${UI_TRASH}</button></div></div>`).join('');box.querySelectorAll('[data-img-alt]').forEach(input=>input.oninput=()=>{editorImages[Number(input.dataset.imgAlt)].description=input.value;imagesChanged=true});box.querySelectorAll('[data-img-remove]').forEach(b=>b.onclick=()=>{editorImages.splice(Number(b.dataset.imgRemove),1);imagesChanged=true;renderEditorImages()});box.querySelectorAll('[data-img-up]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.imgUp);[editorImages[i-1],editorImages[i]]=[editorImages[i],editorImages[i-1]];imagesChanged=true;renderEditorImages()});box.querySelectorAll('[data-img-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.imgDown);[editorImages[i+1],editorImages[i]]=[editorImages[i],editorImages[i+1]];imagesChanged=true;renderEditorImages()});$('#image-help').textContent=editorImages.length?`선택된 이미지 ${editorImages.length}장`:''}
async function getNoteImages(id){const filter='note_id=eq.'+encodeURIComponent(id);const [a,b]=await Promise.all([fetch(BASE+'/rest/v1/study_images?select=id,data_url'+(descriptionsAvailable?',alt_text':'')+'&'+filter,{headers}),fetch(BASE+'/rest/v1/study_files?select=id,path'+(descriptionsAvailable?',alt_text':'')+'&'+filter,{headers})]);if(!a.ok||!b.ok)throw Error('기존 이미지를 불러오지 못했습니다.');const legacy=await a.json(),files=await b.json();files.sort((x,y)=>x.path.split('/').pop().localeCompare(y.path.split('/').pop()));return legacy.filter(x=>/^data:image\/(jpeg|png|webp|gif);base64,[A-Za-z0-9+/=]+$/.test(x.data_url)).map(x=>({src:x.data_url,description:x.alt_text||'',existing:true})).concat(files.filter(x=>/^[0-9a-f]{64}\/[0-9a-f-]{36}\.(jpg|png|webp|gif)$/.test(x.path)).map(x=>({src:fileUrl(x.path),description:x.alt_text||'',existing:true})))}
function lastAuthor(){try{return ['mine','bora'].includes(localStorage.getItem('study-last-author'))?localStorage.getItem('study-last-author'):'mine'}catch{return 'mine'}}
async function openEditor(id=null){editingId=id;let n=notes.find(x=>x.id===id);$('#note-form').reset();editorImages=[];imagesChanged=false;editorLoading=!!n;$('#note-images').disabled=editorLoading;$('#note-form button[type=submit]').disabled=editorLoading;$('#form-heading').textContent=n?'기록 수정':'새 연구 기록';$('#author').value=n?.author||lastAuthor();$('#note-title').value=n?.title||'';$('#note-body').value=n?.body||'';const context=virtualPerson(currentPerson);$('#note-body').placeholder=context?.kind==='family'?'함께 살펴본 내용과 더 알아볼 질문을 적어 보세요.':'기억하고 싶은 내용을 적어 보세요.';$('#note-book').value=n?.book||(context?.kind==='book'?context.display:'');$('#note-verse').value=n?.verse||(context?.kind==='verse'?context.display:'');$('#note-topic').value=n?.topic||(context?.kind==='topic'?context.display:context?.kind==='family'?(new URLSearchParams(location.hash.split('?')[1]||'').get('topic')||''):'');$('#note-url').value=n?.reference_url||'';draftBaseline=draftSnapshot();$('#form-message').textContent='';try{const saved=JSON.parse(localStorage.getItem(draftKey())||'null');if(saved){for(const field of draftFields)if(typeof saved[field]==='string')$('#'+field).value=saved[field];$('#form-message').textContent='이 기기에 임시 저장된 글을 불러왔습니다. 사진과 비밀번호는 다시 선택해 주세요.'}}catch{}renderEditorImages();$('#edit-dialog').showModal();if(n)try{const loaded=await getNoteImages(id);if($('#edit-dialog').open&&editingId===id){editorImages=loaded;renderEditorImages();editorLoading=false;$('#note-images').disabled=false;$('#note-form button[type=submit]').disabled=false}}catch(e){$('#form-message').textContent='기존 이미지를 불러오지 못했습니다. 창을 닫고 다시 시도해 주세요.'}}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('이미지를 읽지 못했습니다.'));r.readAsDataURL(file)})}
async function compress(file){if(file.type==='image/gif')return fileData(file);const img=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);img.close();let converted=canvas.toDataURL('image/webp',.8);return converted.length<file.size*1.333?converted:await fileData(file)}
$('#discard-draft').onclick=()=>{if(!confirm('이 기기의 임시 글과 선택한 이미지를 지울까요? 저장된 기록은 유지됩니다.'))return;try{localStorage.removeItem(draftKey())}catch{}const id=editingId;$('#edit-dialog').close();openEditor(id)};
$('#note-form').addEventListener('input',saveDraft);$('#note-form').addEventListener('change',saveDraft);
$('#note-images').addEventListener('change',async e=>{const files=Array.from(e.target.files);e.target.value='';if(editorImages.length+files.length>3||files.some(f=>f.size>5242880||!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type))){$('#form-message').textContent='이미지는 JPG·PNG·WebP·GIF로 최대 3장, 한 장당 5MB 이하로 선택해 주세요.';return}const btn=$('#note-form button[type=submit]');editorLoading=true;btn.disabled=true;try{for(const file of files)editorImages.push({src:await fileData(file),file});if(files.length)imagesChanged=true;renderEditorImages();$('#form-message').textContent=''}catch{$('#form-message').textContent='이미지를 읽지 못했습니다.'}finally{editorLoading=false;btn.disabled=false}});
$('#note-form').onsubmit=async e=>{e.preventDefault();const form=e.target,btn=form.querySelector('button[type=submit]'),title=$('#note-title').value.trim(),body=$('#note-body').value.trim(),password=$('#note-password').value,url=$('#note-url').value.trim();if(editorLoading)return;if(!title||!body||!password){$('#form-message').textContent='제목, 내용, 비밀번호를 입력해 주세요.';return}if(url&&!safeUrl(url)){$('#form-message').textContent='올바른 자료 링크를 입력해 주세요.';return}btn.disabled=true;$('#form-message').textContent='저장 중입니다…';let saved=false,uploadToken=null;try{const replaceImages=editingId?imagesChanged:editorImages.length>0;const filePaths=[];if(replaceImages&&editorImages.length){uploadToken=await issueUpload(password);for(const img of editorImages){let data;if(img.file)data=await compress(img.file).catch(()=>fileData(img.file));else if(img.src.startsWith('data:'))data=img.src;else{const r=await fetch(img.src);if(!r.ok)throw Error('기존 이미지를 불러오지 못했습니다.');data=await fileData(await r.blob())}filePaths.push(await uploadData(data,uploadToken,filePaths.length))}}await change(editingId?'update':'create',{id:editingId,person:currentPerson,author:$('#author').value,title,body,book:$('#note-book').value.trim(),verse:$('#note-verse').value.trim(),topic:$('#note-topic').value.trim(),reference_url:url,replace_images:replaceImages,images:[],image_descriptions:editorImages.map(img=>img.description||''),file_paths:filePaths,upload_token:uploadToken},password);saved=true;try{localStorage.setItem('study-last-author',$('#author').value);localStorage.removeItem(draftKey())}catch{}imagesChanged=false;cleanup();$('#edit-dialog').close();await load();personView(currentPerson);const m=document.createElement('p');m.className='success-notice';m.setAttribute('role','status');m.textContent='기록을 저장했습니다.';document.querySelector('.notes-list').before(m)}catch(err){if(!saved)await abandon(uploadToken);if(saved){$('#edit-dialog').close();alert('기록은 저장됐지만 화면을 갱신하지 못했습니다. 페이지를 새로고침해 주세요.')}else $('#form-message').textContent=err.message}finally{btn.disabled=false}};
$('#new-era').innerHTML=eraNames.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
$('#person-form').onsubmit=async e=>{e.preventDefault();const name=$('#new-name').value.trim(),btn=e.target.querySelector('button[type=submit],button:not([type])');if(!name)return;if(allPeople().some(p=>p.name===name||displayName(p.name)===name)){$('#person-message').textContent='이미 같은 이름의 인물이 있습니다. 구분할 수 있는 이름을 입력해 주세요.';return}btn.disabled=true;try{await change('person',{name,era:$('#new-era').value,search_term:$('#new-search').value.trim()},$('#person-password').value);$('#person-dialog').close();await load();if(personOrder.ready)openPersonOrder(name);else location.hash=idHash(name)}catch(err){$('#person-message').textContent=err.message}finally{btn.disabled=false}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{const d=b.closest('dialog');if(d.id==='edit-dialog')closeEditor();else d.close()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){if(d.id==='connection-dialog')return;if(d.id==='edit-dialog')closeEditor();else d.close()}}));$('#edit-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEditor()});window.addEventListener('beforeunload',e=>{if($('#edit-dialog').open&&(draftSnapshot()!==draftBaseline||imagesChanged)){saveDraft();e.preventDefault();e.returnValue=''}});
async function getLegacyImages(){let rows=[],offset=0;for(;;){const r=await fetch(BASE+'/rest/v1/study_images?select=id,note_id,data_url'+(descriptionsAvailable?',alt_text':'')+'&order=id.asc&limit=100&offset='+offset,{headers});if(!r.ok)throw Error('이미지를 불러오지 못했습니다.');const page=await r.json();rows.push(...page);if(page.length<100)return rows;offset+=page.length}}
async function getBackupImages(){const legacy=await getLegacyImages();const files=await getAll('study_files','id,note_id,path,'+(descriptionsAvailable?'alt_text,':'')+'created_at');files.sort((a,b)=>a.note_id.localeCompare(b.note_id)||a.path.split('/').pop().localeCompare(b.path.split('/').pop()));const stored=[];for(const f of files){const r=await fetch(fileUrl(f.path));if(!r.ok)throw Error('저장된 이미지를 불러오지 못했습니다.');stored.push({id:f.id,note_id:f.note_id,alt_text:f.alt_text||'',data_url:await fileData(await r.blob())})}return legacy.concat(stored)}
$('#move-images').onclick=async e=>{const button=e.currentTarget;button.disabled=true;let moved=0,token=null;try{const images=await getLegacyImages();if(!images.length){alert('옮길 기존 이미지가 없습니다.');return}if(!confirm(`기존 이미지 ${images.length}개를 파일 저장 공간으로 옮깁니다. 이미지가 확인된 뒤에만 기존 데이터가 삭제됩니다. 계속할까요?`))return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;for(const noteId of [...new Set(images.map(x=>x.note_id))]){const same=images.filter(x=>x.note_id===noteId);token=await issueUpload(password);const mapping=[];for(const image of same)mapping.push({id:image.id,path:await uploadData(image.data_url,token,mapping.length)});const result=await rpc('study_migrate_images',{p_password:password,p_note:noteId,p_upload_token:token,p_mapping:mapping});if(!result?.ok)throw Error(result?.error||'이미지를 옮기지 못했습니다.');token=null;moved+=same.length;button.textContent=`이미지 옮기는 중 (${moved}/${images.length})`}await load();route();alert(`이미지 ${moved}개를 옮겼습니다.`)}catch(err){await abandon(token);alert(`${moved}개를 옮긴 뒤 중단됐습니다. 남은 이미지는 원래 위치에 유지됩니다. ${err.message}`)}finally{button.disabled=false;button.textContent='기존 이미지 옮기기'}};
$('#backup').onclick=async e=>{const password=prompt('전체 백업을 위해 비밀번호를 입력해 주세요.');if(password===null)return;const button=e.currentTarget;button.disabled=true;button.textContent='백업 준비 중…';try{let extra;try{extra=await rpc('study_extra_backup',{p_password:password})}catch(err){if(err.code!=='PGRST202')throw err;if(!confirm('전체 백업 설정이 아직 완료되지 않았습니다. 지금은 연구 기록과 이미지만 백업할까요? 성구와 영적 일과는 포함되지 않습니다.'))return}if(extra&&!extra.ok)throw Error(extra.error||'성구와 일과를 불러오지 못했습니다.');await load();const images=await getBackupImages();const backup={format:'bible-study-backup',version:extra?2:1,exported_at:new Date().toISOString(),people,notes,images,person_order:personOrder.ready?{items:personOrder.items}:null,...(extra?{extra}:{})};const blob=new Blob([JSON.stringify(backup)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='성경연구-백업-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}catch(err){alert('백업을 만들지 못했습니다: '+err.message)}finally{button.disabled=false;button.textContent='백업 내려받기'}};
$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const backup=JSON.parse(await f.text());if(backup.format!=='bible-study-backup'||![1,2].includes(backup.version)||!Array.isArray(backup.notes)||!Array.isArray(backup.images)||!Array.isArray(backup.people))throw Error('지원하지 않는 백업 파일입니다.');if(!confirm('백업의 자료를 현재 자료에 추가합니다. 이미 있는 항목은 유지합니다. 계속할까요?'))return;const password=prompt('작성 비밀번호를 입력해 주세요.');if(password===null)return;if(backup.version===2){if(Array.isArray(backup.extra?.connections)&&!connectionsReady)throw Error('연구 연결 자료를 가져오려면 저장 공간 설정이 필요합니다.');if(!backup.extra||!['verses','preferences','settings','checks'].every(k=>Array.isArray(backup.extra[k])))throw Error('성구와 일과 백업을 확인해 주세요.');const ready=await rpc('study_extra_backup',{p_password:password});if(!ready?.ok)throw Error(ready?.error||'백업 연결을 확인해 주세요.')}await load();let restored=0,skipped=0;for(const person of backup.people){if(allPeople().some(p=>p.name===person.name))continue;await change('person',{name:person.name,era:person.era,search_term:person.search_term||''},password);people.push(person)}for(const n of backup.notes){if(notes.some(x=>x.person===n.person&&x.author===n.author&&x.title===n.title&&x.body===n.body)){skipped++;continue}const backupImages=backup.images.filter(i=>i.note_id===n.id),images=backupImages.map(i=>i.data_url);let token=null;try{const filePaths=[];if(images.length){token=await issueUpload(password);for(const image of images)filePaths.push(await uploadData(image,token,filePaths.length))}await change('restore',{person:n.person,author:n.author,title:n.title,body:n.body,created_at:n.created_at,verse:n.verse||'',book:n.book||'',topic:n.topic||'',reference_url:n.reference_url||'',images:[],image_descriptions:backupImages.map(i=>i.alt_text||''),file_paths:filePaths,upload_token:token},password);token=null}catch(err){await abandon(token);throw err}notes.push(n);restored++}if(backup.version===2){const result=await rpc('study_extra_restore',{p_password:password,p_data:backup.extra});if(!result?.ok)throw Error(result?.error||'성구와 일과를 가져오지 못했습니다.');await loadHomeVerses();routineData=null}await load();if(personOrder.ready&&!personOrder.items.length&&Array.isArray(backup.person_order?.items)){const known=new Set(allPeople().map(p=>p.name)),seen=new Set(),items=backup.person_order.items.filter(x=>x&&known.has(x.name)&&eraNames.includes(x.era)&&!seen.has(x.name)&&seen.add(x.name));if(items.length){const orderResult=await rpc('study_person_order_save',{p_password:password,p_items:items,p_revision:personOrder.revision});if(!orderResult?.ok)throw Error(orderResult?.error||'인물 순서를 가져오지 못했습니다.');await loadPersonOrder()}}route();alert(`가져오기 완료: 연구 기록 ${restored}개 추가, ${skipped}개 건너뜀.`)}catch(err){alert('가져오기를 완료하지 못했습니다. 일부 항목은 이미 추가됐을 수 있습니다. '+err.message);try{await load();route()}catch{}}finally{e.target.value=''}};
let connections=[],connectionsReady=false,symmetricConnections=false,personSelect=null,pendingConnection=null,connectionBaseline='';
async function loadConnections(){try{connections=await getAll('study_connections');connectionsReady=true;try{const r=await rpc('study_connection_capabilities',{});symmetricConnections=!!r?.symmetric_person_connections}catch{symmetricConnections=false}}catch{connections=[];connectionsReady=false;symmetricConnections=false}}
function connectionSection(kind,source,title){
 if(!connectionsReady)return '';
 const list=connections.filter(c=>c.kind===kind&&(c.source===source||(kind==='person'&&symmetricConnections&&c.target===source)));
 if(!list.length)return `<div class="connection-empty"><span>${esc(title)}</span><button type="button" class="action-icon" data-connection-add="${kind}" aria-label="${esc(title)} 추가" title="${esc(title)} 추가">${UI_PLUS}</button></div>`;
 return `<section class="connections-section"><div class="connection-heading"><h2>${esc(title)}</h2><button type="button" class="action-icon" data-connection-add="${kind}" aria-label="${esc(title)} 추가" title="${esc(title)} 추가">${UI_PLUS}</button></div>${list.map(c=>{let target=kind==='person'?(c.source===source?c.target:c.source):c.target;let link=kind==='resource'?`<a href="${esc(safeUrl(target)||'#')}" target="_blank" rel="noopener noreferrer">${esc(c.title)} ↗</a>`:kind==='person'?`<a href="${idHash(target)}">${esc(displayName(target))} →</a>`:`<strong>${esc(c.title)}</strong>${target?`<a class="connection-topic" href="${idHash('@topic:'+target)}"># ${esc(target)}</a>`:''}`;return `<div class="connection-item"><div class="connection-content">${link}${c.description?`<p>${esc(c.description)}</p>`:''}</div><div class="connection-actions"><button type="button" class="tool-icon" data-connection-edit="${esc(c.id)}" aria-label="${esc(title)} 수정: ${esc(kind==='person'?displayName(target):c.title)}" title="${esc(title)} 수정">${UI_PENCIL}</button><button type="button" class="tool-icon" data-connection-delete="${esc(c.id)}" aria-label="${esc(title)} 삭제: ${esc(kind==='person'?displayName(target):c.title)}" title="${esc(title)} 삭제">${UI_TRASH}</button></div></div>`}).join('')}</section>`
}
function openConnection(kind,source,id){
 const c=connections.find(x=>x.id===id),isResource=kind==='resource',isPerson=kind==='person',selected=c?(isPerson&&c.source!==source?c.source:c.target):'';
 if(personSelect){personSelect.destroy();personSelect=null}
 $('#connection-form').reset();$('#connection-id').value=id||'';$('#connection-kind').value=kind;$('#connection-source').value=source;
 $('#connection-title').textContent=isResource?(c?'JW 자료 수정':'JW 자료 추가'):isPerson?'인물 찾기':(c?'질문 수정':'다음 질문');
 $('#connection-label').textContent=isResource?'제목':'질문';$('#connection-name').value=c?.title||'';$('#connection-name-label').hidden=isPerson;$('#connection-name').required=!isPerson;
 $('#connection-target-label').hidden=isPerson;$('#connection-target').required=isResource;$('#connection-target').type=isResource?'url':'text';$('#connection-target-text').textContent=isResource?'JW.ORG 주소':'관련 주제 (선택 사항)';$('#connection-target').placeholder=isResource?'https://www.jw.org/…':'';$('#connection-target').value=isPerson?'':(c?.target||'');
 $('#connection-description-label').hidden=isPerson;$('#connection-description-label').open=!!c?.description;$('#connection-description').value=c?.description||'';$('#connection-person-label').hidden=!isPerson;
 const select=$('#connection-person');select.required=false;select.innerHTML='<option value="">인물을 선택하세요</option>';
 if(isPerson){const options=allPeople().filter(x=>x.name!==source).map(x=>({value:x.name,text:x.name==='스가랴'?'스가랴 (예언자)':displayName(x.name),aliases:x.name}));options.forEach(x=>{const option=document.createElement('option');option.value=x.value;option.textContent=x.text;select.append(option)});select.value=selected||'';if(typeof TomSelect!=='undefined')personSelect=new TomSelect(select,{maxItems:1,maxOptions:null,create:false,openOnFocus:!selected,closeAfterSelect:true,sortField:[{field:'$order'}],searchField:['text','aliases'],options,placeholder:'이름을 입력하거나 선택하세요',render:{no_results:()=>'<div class="no-results">일치하는 인물이 없습니다.</div>'}})}
 $('#connection-message').textContent='';connectionBaseline=connectionSnapshot();$('#connection-dialog').showModal();
}
function connectionSnapshot(){return JSON.stringify({kind:$('#connection-kind').value,name:$('#connection-name').value,target:$('#connection-target').value,person:$('#connection-person').value,typing:personSelect?.control_input?.value||'',description:$('#connection-description').value})}
function closeConnectionEditor(){if(!$('#connection-dialog').open)return;if(connectionSnapshot()!==connectionBaseline){$('#connection-discard-dialog').showModal();return}$('#connection-dialog').close()}
$('#connection-dialog [data-close]').onclick=closeConnectionEditor;
$('#connection-dialog').addEventListener('cancel',e=>{e.preventDefault();closeConnectionEditor()});
$('#connection-keep').onclick=()=>$('#connection-discard-dialog').close();
$('#connection-discard').onclick=()=>{$('#connection-discard-dialog').close();$('#connection-dialog').close()};
window.addEventListener('beforeunload',e=>{if($('#connection-dialog').open&&connectionSnapshot()!==connectionBaseline){e.preventDefault();e.returnValue=''}});
let connectionToastTimer;
function showConnectionToast(message){let toast=$('#connection-toast');if(!toast){toast=document.createElement('div');toast.id='connection-toast';toast.className='connection-toast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.append(toast)}clearTimeout(connectionToastTimer);toast.textContent=message;toast.hidden=false;connectionToastTimer=setTimeout(()=>{toast.hidden=true},3200)}
function requestConnectionPassword(action,data,context){pendingConnection={action,data,context};$('#connection-password').value='';$('#connection-auth-title').textContent=action==='delete'?'삭제 확인':'비밀번호';$('#connection-auth-context').textContent=action==='delete'?`${context}을(를) 삭제할까요?`:'';$('#connection-auth-message').textContent='';$('#connection-auth-submit').textContent=action==='delete'?'삭제':'저장';$('#connection-auth-dialog').showModal();$('#connection-password').focus()}
function bindConnections(source){
 document.querySelectorAll('[data-connection-add]').forEach(b=>b.onclick=()=>openConnection(b.dataset.connectionAdd,source));
 document.querySelectorAll('[data-connection-edit]').forEach(b=>b.onclick=()=>{const c=connections.find(x=>x.id===b.dataset.connectionEdit);if(c)openConnection(c.kind,source,c.id)});
 document.querySelectorAll('[data-connection-delete]').forEach(b=>b.onclick=()=>{const c=connections.find(x=>x.id===b.dataset.connectionDelete);if(c)requestConnectionPassword('delete',{id:c.id},c.kind==='person'?displayName(c.source===source?c.target:c.source):c.title)});
}
$('#connection-form').onsubmit=e=>{
 e.preventDefault();const kind=$('#connection-kind').value,source=$('#connection-source').value,id=$('#connection-id').value,name=$('#connection-name').value.trim();let target=$('#connection-target').value.trim(),title=name;
 if(kind==='person'){target=$('#connection-person').value;if(!allPeople().some(p=>p.name===target)||target===source){$('#connection-message').textContent='목록에서 다른 인물을 선택해 주세요.';return}if(connections.some(c=>c.kind==='person'&&c.id!==id&&((c.source===source&&c.target===target)||(c.source===target&&c.target===source)))){$('#connection-message').textContent='이미 연결된 인물입니다.';return}title=displayName(target)}
 if(kind==='resource'){try{const u=new URL(target);if(u.protocol!=='https:'||!(u.hostname==='jw.org'||u.hostname.endsWith('.jw.org')))throw Error()}catch{$('#connection-message').textContent='JW.ORG 자료 주소를 입력해 주세요.';return}}
 const data={id,kind,source,title,target,description:$('#connection-description').value.trim()};requestConnectionPassword(id?'update':'create',data,title);
};
$('#connection-auth-form').onsubmit=async e=>{e.preventDefault();if(!pendingConnection)return;const btn=$('#connection-auth-submit'),task=pendingConnection;btn.disabled=true;try{const r=await rpc('study_connection_change',{p_password:$('#connection-password').value,p_action:task.action,p_data:task.data});if(!r?.ok)throw Error(r?.error||'처리하지 못했습니다.');await loadConnections();pendingConnection=null;$('#connection-auth-dialog').close();if($('#connection-dialog').open)$('#connection-dialog').close();personView(currentPerson);showConnectionToast(connectionsReady?(task.action==='delete'?'삭제했어요.':'저장했어요.'):'처리는 완료됐지만 목록을 불러오지 못했어요. 새로고침해 주세요.')}catch(err){$('#connection-auth-message').textContent=err.message}finally{btn.disabled=false}};

function topicQuestions(topic){const found=connections.filter(c=>c.kind==='question'&&c.target===topic);return found.length?`<section class="connections-section"><h2>가족 숭배 질문</h2>${found.map(c=>`<a class="topic-question" href="${idHash(c.source)}">${esc(c.title)} <span>→</span></a>`).join('')}</section>`:''}
$('#home-verse-form').onsubmit=setHomeVerse;$('#home-verse-mode').onchange=e=>changeVerse('mode',{mode:e.target.value});$('#home-verse-cancel').onclick=()=>{$('#home-verse-id').value='';$('#home-verse-reference').value='';$('#home-verse-text').value='';$('#home-verse-save').textContent='+ 성구 저장';$('#home-verse-cancel').hidden=true};$('#routine-setting-form').onsubmit=saveRoutineSetting;window.addEventListener('hashchange',route);async function start(){let timer;try{await Promise.race([Promise.all([load(),loadHomeVerses()]),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('시간 초과')),12000)})]);route();cleanup()}catch(e){appMessage('기록을 불러오지 못했습니다. 연결 상태를 확인해 주세요.')}finally{clearTimeout(timer)}}start();
